import { ActionMetrics, SimResult, SimResultFilter } from '../../proto_utils/sim_result.js';
import { formatDeltaTextElem } from '../../utils.js';

import { ColumnSortType, MetricsTable } from './metrics_table.js';
import { ResultComponent, ResultComponentConfig, SimResultData } from './result_component.js';

export class CastMetricsTable extends MetricsTable<ActionMetrics> {
	constructor(config: ResultComponentConfig) {
		config.rootCssClass = 'cast-metrics-root';
		
		let lastSimResult: SimResultData | null = null;
		config.resultsEmitter.on((eventID, resultData) => {
			lastSimResult = resultData;
		});

		const renderDiffCell = (metric: ActionMetrics, cellElem: HTMLElement, getValue: (m: ActionMetrics) => number, precision: number, isPercent: boolean = false, lowerIsBetter: boolean = false) => {
			const val = getValue(metric);
			cellElem.innerHTML = '';
			const baseSpan = document.createElement('span');
			baseSpan.textContent = val.toFixed(precision) + (isPercent ? '%' : '');

			if (lastSimResult && lastSimResult.referenceResult) {
				const refPlayers = lastSimResult.referenceResult.getPlayers(lastSimResult.filter);
				const curPlayers = lastSimResult.result.getPlayers(lastSimResult.filter);
				
				if (refPlayers.length === 1 && curPlayers.length === 1) {
					const refPlayer = refPlayers[0];
					const curPlayer = curPlayers[0];
					
					let refRawActions: ActionMetrics[] = [];
					let curRawActions: ActionMetrics[] = [];
					
					// Fetching from the main .actions array for Casts
					if (metric.unit?.isPet) {
						const refPet = refPlayer.pets.find(p => p.name === metric.unit?.name);
						if (refPet) refRawActions = refPet.actions.filter(a => a.casts != 0).map(a => a.forTarget(lastSimResult!.filter));
						
						const curPet = curPlayer.pets.find(p => p.name === metric.unit?.name);
						if (curPet) curRawActions = curPet.actions.filter(a => a.casts != 0).map(a => a.forTarget(lastSimResult!.filter));
					} else {
						refRawActions = refPlayer.actions.filter(a => a.casts != 0).map(a => a.forTarget(lastSimResult!.filter));
						curRawActions = curPlayer.actions.filter(a => a.casts != 0).map(a => a.forTarget(lastSimResult!.filter));
					}

					const curGroups = ActionMetrics.groupById(curRawActions);
					const matchingGroup = curGroups.find(g => g.some(a => a.actionId.equals(metric.actionId)));

					if (matchingGroup) {
						const groupCasts = matchingGroup.reduce((sum, a) => sum + a.casts, 0);
						const isParent = Math.abs(metric.casts - groupCasts) < 0.1;

						let refVal: number | null = null;

						if (isParent) {
							const refGroups = ActionMetrics.groupById(refRawActions);
							const matchingRefGroup = refGroups.find(g => g.some(a => a.actionId.equals(metric.actionId)));
							if (matchingRefGroup) {
								const mergedRef = ActionMetrics.merge(matchingRefGroup, true, metric.unit?.petActionId || undefined);
								refVal = getValue(mergedRef);
							}
						} else {
							const refAction = refRawActions.find(a => a.actionId.equals(metric.actionId));
							if (refAction) refVal = getValue(refAction);
						}

						if (refVal !== null && val !== refVal) {
							const deltaSpan = document.createElement('span');
							formatDeltaTextElem(deltaSpan, refVal, val, precision, lowerIsBetter, false, false);
							if (isPercent) deltaSpan.textContent += '%';
							
							deltaSpan.textContent = `(${deltaSpan.textContent})`;
							deltaSpan.style.marginRight = '6px';
							deltaSpan.style.fontSize = '0.65em';
							deltaSpan.style.opacity = '0.85'; 
							deltaSpan.style.whiteSpace = 'nowrap'; 
							
							cellElem.appendChild(deltaSpan);
						}
					}
				}
			}
			cellElem.appendChild(baseSpan);
		};
		
		super(config, [
			MetricsTable.nameCellConfig((metric: ActionMetrics) => {
				return {
					name: metric.name,
					actionId: metric.actionId,
				};
			}),
			{
				name: 'Casts',
				tooltip: 'Casts',
				sort: ColumnSortType.Descending,
				getValue: (metric: ActionMetrics) => metric.casts,
				//getDisplayString: (metric: ActionMetrics) => metric.casts.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.casts, 1),
			},
			{
				name: 'CPM',
				tooltip: 'Casts / (Encounter Duration / 60 Seconds)',
				getValue: (metric: ActionMetrics) => metric.castsPerMinute,
				//getDisplayString: (metric: ActionMetrics) => metric.castsPerMinute.toFixed(1),
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => renderDiffCell(metric, cellElem, m => m.castsPerMinute, 1),
			},
		]);
	}

	getGroupedMetrics(resultData: SimResultData): Array<Array<ActionMetrics>> {
		//const actionMetrics = resultData.result.getActionMetrics(resultData.filter);
		const players = resultData.result.getPlayers(resultData.filter);
		if (players.length != 1) {
			return [];
		}
		const player = players[0];

		const actions = player.actions.filter(action => action.casts != 0).map(action => action.forTarget(resultData.filter));
		const actionGroups = ActionMetrics.groupById(actions);
		const petGroups = player.pets.map(pet => pet.actions.filter(action => action.casts != 0).map(action => action.forTarget(resultData.filter)));

		return actionGroups.concat(petGroups);
	}

	mergeMetrics(metrics: Array<ActionMetrics>): ActionMetrics {
		return ActionMetrics.merge(metrics, true, metrics[0].unit?.petActionId || undefined);
	}

	shouldCollapse(metric: ActionMetrics): boolean {
		return !metric.unit?.isPet;
	}
}
